UPDATE sal_order_line SET shipped_qty = shipped_qty + #{qty}
WHERE tenant_id = #{tenantId} AND id = #{orderLineId}
  AND #{qty} > 0 AND shipped_qty + #{qty} <= ordered_qty

UPDATE sal_credit_account
SET used_amount = used_amount + #{amount}, version = version + 1, updated_at = now()
WHERE tenant_id = #{tenantId} AND customer_id = #{customerId}
  AND used_amount + #{amount} <= #{creditLimit}

UPDATE sal_credit_account
SET used_amount = used_amount + #{amount}, version = version + 1, updated_at = now()
WHERE tenant_id = #{tenantId} AND customer_id = #{customerId}

UPDATE sal_credit_account
SET used_amount = used_amount - #{amount}, version = version + 1, updated_at = now()
WHERE tenant_id = #{tenantId} AND customer_id = #{customerId} AND used_amount >= #{amount}
